// Show the session title in the prompt, dimmed, at the right end of the
// agent/model row, the way Claude Code shows it on the input box. Otherwise the
// only place to see it is the terminal tab.
//
// Renders into the session_prompt_right slot. The title comes from session
// state, so it updates when the session is renamed or auto-titled.
//
// Options (tui.json):
//   max   most columns the title takes before it is cut with "..."   (default 48)
//   min   fewest columns worth showing; narrower than this, it hides  (default 12)
import { createElement, effect, insert, setProp } from "@opentui/solid"
import { createSignal } from "solid-js"

const DEFAULTS = { max: 48, min: 12 }

const tui = async (api, rawOptions) => {
  if (typeof api.slots?.register !== "function") return
  const options = { ...DEFAULTS, ...(rawOptions ?? {}) }
  api.slots.register({
    order: 100,
    slots: {
      session_prompt_right(_ctx, props) {
        // Text renderables never call onSizeChange, so a box does the measuring.
        const root = createElement("box")
        const text = createElement("text")
        const [width, setWidth] = createSignal(Infinity)
        setProp(root, "flexShrink", 1)
        setProp(root, "minWidth", 0)
        setProp(root, "maxWidth", options.max)
        setProp(root, "onSizeChange", function () {
          setWidth(this.width)
        })
        setProp(text, "wrapMode", "none")
        setProp(text, "truncate", true)
        setProp(text, "flexShrink", 1)
        setProp(text, "minWidth", 0)
        // Hiding by color (the prompt background) keeps the text in the layout.
        // Dropping it would free the space, and the size it reports would never
        // grow back past min.
        effect((prev) => {
          const title = api.state.session.get(props.session_id)?.title ?? ""
          const cut = width() < Math.min(options.min, title.length)
          return setProp(text, "fg", cut ? api.theme.current.backgroundElement : api.theme.current.textMuted, prev)
        })
        insert(text, () => api.state.session.get(props.session_id)?.title ?? "")
        insert(root, text)
        return root
      },
    },
  })
}

export default { id: "session-title", tui }
